        block=page.split('Table 9:')[0]
    elif number==10:
        block=page.split('Table 9:')[1].split('Table 10:')[0]
    elif number==11:
        block=page.split('Table 11:')[0]
    elif number==12:
        block=page.split('Table 11:')[1].split('Table 12:')[0]
    else:
        block=page.split('Table 13:')[0]
    print(f'Table {number}: average discrepancies larger than 0.02 pp')
    for line in block.splitlines():
        parts=re.split(r'\\s{2,}',line.strip())
        size_idx=next((i for i,s in enumerate(parts) if re.fullmatch(r'\\d+(?:\\.\\d+)?[MB]\\*?',s)),None)
        if size_idx is None:
            continue
        vals=[]
        for part in parts[size_idx+1:]:
            try:
                vals.append(float(part))
            except ValueError:
                pass
        if len(vals)<n_metrics+1:
            continue
        actual=sum(vals[:n_metrics])/n_metrics
        reported=vals[n_metrics]
        if abs(actual-reported)>.02:
            print(' | '.join(parts[:size_idx+1]), vals, 'calculated=',round(actual,4),'reported=',reported)
print('\\nTraining-token accounting from Table 16:')
for name,batch,acc,steps,reported in [('Bangla',32,8,100000,26.21),('Hindi',32,16,150000,66),('Marathi',32,8,100000,28.83),('Tamil',32,8,100000,39.32),('Telugu',16,16,100000,39.32)]:
